command:
set -euo pipefail
export PATH=/opt/conda/bin:$PATH
export TMPDIR=/tmp HOME=/tmp
cd /tmp

echo "== four samples whose FastQC metrics are fixed by construction =="
gen(){ # name nreads readlen gcpct ndup
  awk -v out="$1.fastq" -v N="$2" -v L="$3" -v GC="$4" -v NDUP="$5" 'BEGIN{
    srand(53); nGC = L*GC/100
    if (nGC != int(nGC)) { print "FIXTURE: GC pct not exact at this read length" > "/dev/stderr"; exit 1 }
    q=""; for(i=0;i<L;i++) q=q "I"
    for(i=1;i<=L;i++) slot[i] = (i<=nGC) ? "GC" : "AT"
    for(i=L;i>1;i--){ j=int(rand()*i)+1; t=slot[i]; slot[i]=slot[j]; slot[j]=t }
    dup=""
    for(i=1;i<=L;i++) dup = dup ( slot[i]=="GC" ? (rand()<0.5?"G":"C") : (rand()<0.5?"A":"T") )
    n=0
    for(r=1;r<=N;r++){
      n++
      if (r <= NDUP) { s = dup }
      else {
        for(i=1;i<=L;i++) slot[i] = (i<=nGC) ? "GC" : "AT"
        for(i=L;i>1;i--){ j=int(rand()*i)+1; t=slot[i]; slot[i]=slot[j]; slot[j]=t }
        s=""
        for(i=1;i<=L;i++) s = s ( slot[i]=="GC" ? (rand()<0.5?"G":"C") : (rand()<0.5?"A":"T") )
      }
      printf "@%s_read%d\n%s\n+\n%s\n", out, r, s, q > out
    }
    # planted truth: sample, reads, length, GC pct, and the EXACT dedup pct 100*(N-NDUP+1)/N
    dd = (NDUP>0) ? 100*(N-NDUP+1)/N : 100
    printf "%s\t%d\t%d\t%d\t%.1f\n", substr(out,1,length(out)-6), n, L, GC, dd
  }'
}
: > truth.tsv
gen sampleA 1000 100 50   0 >> truth.tsv
gen sampleB 1000 100 25   0 >> truth.tsv
gen sampleC  800  50 50   0 >> truth.tsv
gen sampleD 1000 100 50 500 >> truth.tsv
printf 'sample\treads\tlen\tGC\tdedup\n'; cat truth.tsv

echo "== verify the fixture by counting bases, independently of the generator =="
while IFS=$'\t' read -r s n l g d; do
  OBS=$(awk 'NR%4==2{ tot+=length($0); gc+=gsub(/[GCgc]/,"") } END{ printf "%.4f", 100*gc/tot }' "$s.fastq")
  awk -v o="$OBS" -v e="$g" -v s="$s" 'BEGIN{ if (o+0 != e+0) { printf "FIXTURE: %s GC is %s, planted %s\n", s, o, e; exit 1 } }'
  printf 'fixture_%s\t%s reads x %s bp, GC %s%% (counted %s%%), dedup %s%%\n' "$s" "$n" "$l" "$g" "$OBS" "$d"
done < truth.tsv | tee fixture.txt

echo "== FastQC =="
fastqc --version > fqver.txt 2>&1
FV=$(awk 'NR==1{print $2}' fqver.txt)
fastqc -t 2 --extract -o . sampleA.fastq sampleB.fastq sampleC.fastq sampleD.fastq > fq.log 2>&1 \
  || { tail -15 fq.log; exit 1; }

echo "== FastQC's own numbers, pulled from fastqc_data.txt =="
: > fastqc_values.tsv
while IFS=$'\t' read -r s n l g d; do
  awk -F'\t' -v s="$s" '/^Total Sequences/{ts=$2} /^Sequence length/{sl=$2} /^%GC/{gc=$2}
    /^#Total Deduplicated Percentage/{dd=$2}
    END{ printf "%s\t%s\t%s\t%s\t%s\n", s, ts, sl, gc, dd }' "${s}_fastqc/fastqc_data.txt" >> fastqc_values.tsv
done < truth.tsv
printf 'sample\treads\tlen\tGC\tdedup\n'; cat fastqc_values.tsv

echo "== every FastQC metric must equal the planted value =="
paste truth.tsv fastqc_values.tsv | awk -F'\t' '{
  if ($6 != $1)                { printf "sample name mismatch: %s vs %s\n", $1, $6; bad=1 }
  if ($7+0 != $2+0)            { printf "%s total sequences %s, planted %s\n", $1, $7, $2; bad=1 }
  if ($8+0 != $3+0)            { printf "%s read length %s, planted %s\n", $1, $8, $3; bad=1 }
  if ($9+0 != $4+0)            { printf "%s GC %s, planted %s\n", $1, $9, $4; bad=1 }
  if ($10+0 != $5+0)           { printf "%s dedup %s, planted %s\n", $1, $10, $5; bad=1 }
} END{ if (bad) exit 1; print "all four samples exact" }'

TOTREADS=$(awk -F'\t' '{n+=$2} END{print n}' truth.tsv)
{
printf 'FastQC -- four samples whose metrics are fixed by construction\n'
printf 'fastqc_version\t%s\n' "$FV"
printf 'samples\t4   (assert 4 reports)\n'
printf 'total_sequences_exact\tyes   (assert yes -- EXACT per sample)\n'
printf 'read_length_exact\tyes   (assert yes -- EXACT)\n'
printf 'gc_exact\tyes   (assert yes -- EXACT: each read carries a fixed count of G/C bases)\n'
printf 'dedup_exact\tyes   (assert yes -- EXACT: 500 copies of one read + 500 unique = 501/1000 = 50.1%%)\n'
printf 'cohort_reads\t%s   (the conservation total the aggregator must reproduce)\n' "$TOTREADS"
} | tee smoke-check-fastqc.txt
echo "FASTQC CHECK PASSED"
